\u003a\u0071\u002c\u007a\u0060\u004f\u0042\u006a\u004d\u0074\u0060\u0043\u0045\u0047\u0033\u007c\u0063\u0042\u003c\u002b\u0066\u005f\u0077\u0023\u0079\u0038\u004c\u0035\u007a\u004d\u004f\u007b\u0047\u0043\u005e\u003d\u006c\u0026\u0040\u0054\u007b\u0041\u0038\u005f\u004d\u0075\u0045\u003c\u002a\u0057\u005f\u0048\u004f\u007a\u004c\u0052\u0035\u0075\u0067\u003f\u007e\u0044\u003d\u0074\u0023\u0066\u006f\u0031\u0032\u0053\u0042\u0040\u002b\u007e\u0045\u006e\u0051\u004f\u0055\u007c\u004a\u0039\u0068\u0046\u007e\u0051\u0073\u005f\u006f\u0048\u0079\u006c\u002c\u0030\u0032\u006d\u0047\u0065\u0025\u0063\u0063\u0021\u0059\u0058\u0024\u006a\u007e\u004f\u0066\u0036\u0045\u005e\u0051\u007c\u0041\u004e\u002b\u0025\u0049\u0047\u006d\u003c\u007c\u003d\u0076\u0067\u0037\u0024\u004e\u0053\u004a\u0074\u006a\u005a\u0038\u0063\u006b\u0065\u0050\u003c\u003c\u0074\u0057\u0055\u0035\u0057\u0047\u0033\u0039\u0066\u0074\u0054\u0036\u0058\u0066\u0053\u0049\u0037\u0058\u0033\u0047\u0033\u0039\u0066\u0074\u0054\u0032\u0074\u0071\u0076\u0042\u0075\u002b\u0035\u0034\u0052\u005f\u005a\u0049\u0034\u0074\u006c\u0028\u005d\u006e\u007e\u0050\u006d\u0022\u0071\u0058\u002e\u0068\u006e\u007b\u0024\u002f\u006d\u0022\u0071\u0063\u007d\u0063\u0058\u0045\u006b\u0032\u0049\u0078\u0028\u0040\u0077\u006d\u004a\u0072\u0030\u0021\u005e\u0046\u007c\u0073\u004b\u0049\u0078\u005f\u006f\u0075\u0061\u0078\u0036\u005a\u0035\u0026\u0033\u007c\u0041\u0066\u0025\u003e\u0067\u0022\u003b\u0072\u0073\u007a\u0063\u0041\u0045\u0047\u0024\u004c\u006d\u0031\u0064\u0062\u0054\u0024\u0068\u0028\u0070\u0047\u006b\u0065\u005b\u0060\u0058\u002f\u0022\u003d\u0070\u0063\u003b\u0036\u004a\u0046\u005a\u0067\u0067\u0050\u0044\u004c\u0061\u0063\u0048\u0071\u0063\u003a\u005d\u0022\u0048\u0053\u0059\u0066\u005d\u004e\u0046\u005a\u002c\u0078\u0054\u0060\u0051\u0036\u0044\u0060\u0026\u0065\u0041\u0051\u005b\u0029\u0034\u003c\u0035\u0055\u004b\u0060\u006e\u0052\u007e\u0046\u006d\u004d\u0048\u0022\u0054\u0050\u0033\u003e\u0052\u007b\u0079\u0077\u0063\u004d\u004d\u0033\u0047\u007c\u0072\u0076\u007a\u0048\u0059\u0024\u007d\u0035\u003d\u006d\u005f\u0076\u0043\u0069\u0022\u0063\u004d\u002c\u007c\u004e\u006e\u0043\u007a\u0069\u0052\u003b\u0046\u0026\u0072\u002c\u0047\u004e\u0039\u002a\u0068\u0042\u0070\u006f\u0022\u0025\u0046\u0057\u006f\u0029\u005f\u0068\u004c\u0021\u0049\u0053\u0033\u004f\u003d\u0025\u0071\u0042\u0026\u004f\u003d\u005f\u0052\u0023\u0031\u0045\u0022\u0041\u005f\u007d\u005f\u0061\u0040\u005e\u0040\u0038\u004c\u0038\u0055\u0045\u0045\u0022\u003d\u0035\u0033\u0067\u0045\u0052\u003f\u003b\u0073\u0045\u003a\u0063\u002e\u0056\u0039\u0078\u0050\u0059\u003d\u0077\u006c\u0061\u0047\u0067\u0060\u0078\u0043\u0061\u0022\u003b\u004d\u0040\u0065\u007d\u006a\u0045\u0055\u005a\u0064\u006a\u0045\u0052\u007c\u0026\u0073\u0057\u006c\u006b\u0070\u006d\u003e\u0025\u0034\u003d\u0032\u0045\u0056\u0078\u0068\u007d\u002e\u0046\u0064\u0062\u0053\u0025\u0040\u0041\u005b\u0071\u007e\u0033\u006c\u0031\u007b\u0061\u003c\u0041\u004e\u004d\u0047\u0048\u004d\u006f\u0060\u003a\u0045\u0030\u0059\u0058\u002a\u0056\u0052\u004c\u0029\u003d\u003c\u0034\u0075\u002c\u007d\u005a\u0065\u002e\u007d\u0042\u0040\u002c\u004d\u003f\u0069\u0025\u0038\u003e\u006a\u0070\u0032\u0070\u006c\u003d\u0066\u0075\u0030\u0073\u006b\u0079\u007e\u0051\u003c\u004d\u0062\u007d\u0039\u0034\u0064\u0062\u003a\u0071\u0028\u002e\u0079\u004e\u0056\u0055\u0063\u005d\u0065\u0067\u007c\u0021\u0066\u0037\u0047\u003a\u0053\u0056\u007c\u0046\u0025\u002e\u0070\u006b\u0028\u0077\u004f\u0076\u004d\u0044\u002c\u002f\u007a\u0062\u0057\u0050\u0078\u0051\u002a\u0066\u006a\u004d\u0035\u0025\u0055\u003d\u006f\u0029\u0066\u0023\u0034\u0030\u0026\u0023\u0078\u0069\u0065\u002e\u005d\u0042\u004e\u006c\u0058\u006a\u003a\u006e\u0026\u0062\u0029\u005d\u0067\u006b\u0050\u0024\u0022\u0053\u005a\u0045\u0056\u0034\u006a\u0033\u0072\u0030\u0051\u007e\u0057\u0021\u0049\u004c\u0044\u0029\u002c\u005d\u004e\u0042\u0054\u004a\u003b\u0038\u0028\u0038\u005d\u004c\u002c\u004d\u004e\u0028\u0055\u0061\u0023\u0066\u0079\u006e\u0024\u0043\u0032\u0039\u0063\u002b\u0073\u002b\u0054\u0046\u002e\u0052\u004c\u007e\u0061\u0064\u0051\u004d\u0053\u0042\u0048\u0075\u006b\u0072\u006f\u0070\u005e\u0079\u007c\u0067\u0060\u003c\u007a\u0048\u0022\u0021\u0059\u0060\u0034\u0060\u0025\u006c\u005f\u0068\u004a\u0033\u002f\u004b\u0063\u0063\u0039\u007d\u0078\u0066\u007b\u005d\u003c\u0078\u0024\u0057\u006b\u002e\u0024\u0073\u0064\u0067\u0067\u0041\u0046\u0055\u0044\u005a\u0040\u007d\u0031\u0024\u0073\u0047\u0069\u0022\u0064\u003e\u0046\u007b\u0072\u0072\u003a\u003b\u007e\u0041\u0037\u0044\u0061\u0048\u005a\u007b\u002a\u007c\u0054\u0043\u005b\u004c\u003d\u004c\u0042\u0043\u007b\u0054\u0079\u005b\u0046\u0062\u002e\u0045\u0031\u0051\u004b\u0055\u006a\u0023\u0068\u0058\u0038\u0034\u0028\u0076\u0022\u002c\u007c\u007b\u0039\u006d\u0031\u0031\u0063\u005f\u0022\u004a\u0040\u0044\u0073\u0047\u0069\u005b\u0041\u0062\u0063\u005f\u0065\u0048\u0048\u0029\u0049\u0064\u003f\u0072\u0077\u0072\u006c\u007b\u002e\u0061\u007b\u002b\u0067\u002c\u0072\u003a\u003a\u0044\u0036\u0028\u004d\u0034\u0037\u0072\u0039\u0065\u003c\u0074\u0052\u0062\u0063\u003d\u0040\u0047\u007b\u0022\u0037\u003e\u0022\u005a\u0045\u0060\u0046\u0077\u006c\u0073\u0074\u0064\u006f\u0024\u0078\u0062\u0058\u0055\u006a\u006a\u0046\u003b\u0072\u0052\u0074\u003d\u0066\u0047\u004f\u006d\u006a\u0057\u006c\u0078\u0077\u0036\u004d\u003d\u0079\u004f\u0040\u0077\u005f\u002c\u0040\u0021\u007a\u0053\u003f\u0069\u004d\u002b\u004d\u0023\u0073\u0029\u002b\u0042\u0039\u0070\u0071\u005e\u0043\u0034\u0035\u0038\u007c\u0067\u003f\u0032\u007e\u003e\u0033\u005e\u0043\u0073\u0061\u006d\u007c\u0068\u0051\u004b\u0029\u0051\u0056\u0030\u007e\u0068\u0060\u0040\u0047\u005f\u0054\u007d\u004c\u002e\u0033\u0058\u0023\u0037\u0031\u0034\u005d\u0058\u0046\u0066\u003f\u007a\u0051\u0047\u0068\u0054\u0076\u0021\u0052\u003e\u0051\u0044\u0051\u0030\u007c\u007a\u0068\u006f\u0072\u0076\u0064\u0024\u007c\u004a\u0054\u0073\u002c\u0042\u0021\u0079\u003f\u0072\u003c\u0075\u0060\u005d\u0070\u0057\u004e\u0035\u0067\u006f\u0072\u0071\u0042\u0065\u007c\u003b\u0074\u002b\u005b\u0036\u0065\u0031\u005b\u003c\u0025\u006c\u0047\u0030\u003d\u0069\u0040\u0043\u0023\u007a\u0064\u0061\u0077\u0060\u004e\u005e\u0029\u004a\u0024\u0066\u0049\u0043\u0057\u0051\u006f\u003f\u0067\u005f\u0069\u0074\u006e\u006b\u0062\u007b\u005b\u0074\u0060\u0028\u0069\u007c\u0062\u006a\u0045\u0037\u0061\u0037\u006e\u002e\u006a\u0076\u0042\u007b\u003d\u0069\u003b\u0048\u0073\u003c\u0053\u0076\u005b\u0030\u007e\u0069\u002c\u006b\u006a\u0068\u0052\u006b\u003b\u0031\u0028\u0063\u0025\u006c\u0037\u0069\u0050\u007b\u0022\u007b\u0073\u003c\u0053\u0076\u005b\u0030\u006e\u0045\u005d\u0034\u0054\u0031\u0031\u0041\u0071\u0073\u004f\u0063\u004a\u0059\u0023\u0064\u0026\u0068\u0069\u0021\u002f\u004a\u0037\u0057\u0062\u002a\u0037\u0040\u0034\u004e\u005b\u003c\u0072\u0049\u003f\u0063\u0052\u0029\u0057\u0039\u0050\u0038\u0024\u002b\u0035\u004d\u003f\u004f\u007b\u0075\u0039\u0079\u0033\u002e\u002c\u002c\u0077\u007b\u005f\u0038\u0033\u007b\u005a\u0057\u002c\u0026\u0052\u0074\u0056\u0023\u005d\u0074\u003c\u005f\u004e\u004e\u0053\u003a\u002e\u002e\u0023\u0036\u002f\u0034\u006b\u005e\u005f\u003d\u0064\u0035\u0021\u0069\u004c\u003b\u0060\u0025\u0056\u0023\u005d\u0074\u003c\u005f\u004c\u003b\u0060\u0060\u0025\u002f\u007e\u0064\u0028\u006c\u0065\u0079\u0078\u0058\u0066\u006a\u003c\u004e\u0047\u006c\u0022\u003f\u007a\u0043\u006d\u0046\u0023\u003b\u0060\u0028\u0025\u0031\u0045\u0054\u0076\u0077\u0041\u0024\u0051\u003a\u007b\u0039\u0063\u0059\u0061\u0069\u0059\u0070\u002c\u0056\u006a\u0064\u006e\u002b\u0056\u0052\u0073\u006a\u003f\u006c\u0062\u005b\u002b\u007c\u0048\u0043\u005f\u0063\u0029\u0072\u002e\u0061\u0042\u007e\u007b\u0061\u0046\u006c\u0072\u0066\u0026\u0035\u004d\u007a\u0036\u005b\u006c\u005a\u0045\u005d\u004e\u006c\u0076\u002b\u006d\u0051\u002b\u0063\u0051\u004b\u002a\u0056\u0025\u0061\u0069\u003e\u0042\u0053\u003b\u0034\u007b\u005e\u0047\u0031\u006c\u0026\u0070\u0073\u002e\u0053\u0078\u0062\u007e\u003a\u002f\u005f\u0024\u0069\u0045\u0039\u0064\u004f\u007c\u002f\u006f\u0057\u003e\u006d\u0028\u003f\u0023\u003e\u0041\u0056\u0067\u0072\u0046\u0069\u0028\u0037\u004d\u004a\u0058\u002b\u0041\u0028\u0079\u0056\u0071\u0061\u006f\u0073\u002c\u0039\u0053\u002e\u006a\u002a\u003a\u0049\u0042\u0043\u006d\u0046\u0037\u0025\u0046\u003e\u0028\u002a\u0072\u0046\u0066\u002c\u0034\u0031\u004d\u0024\u0044\u002c\u0060\u0041\u0030\u002c\u003e\u004d\u0052\u0062\u0056\u0064\u0028\u0077\u0028\u006c\u004d\u0078\u0025\u0056\u0077\u004c\u006e\u0038\u0044\u003b\u003c\u002c\u0075\u0077\u0038\u0078\u0029\u0044\u0066\u0037\u0063\u006a\u0061\u0054\u0030\u0038\u0053\u003c\u0058\u0042\u006c\u0030\u0032\u005d\u003e\u0022\u004b\u004e\u005d\u0071\u003b\u004e\u0034\u0065\u0023\u0035\u0063\u0028\u0065\u002c\u0052\u0037\u0038\u007a\u0033\u0071\u003b\u006a\u005a\u004e\u006a\u0036\u0026\u0078\u0057\u003d\u0049\u0036\u003c\u0061\u0065\u0075\u005e\u006d\u006a\u0042\u0032\u0023\u006a\u0043\u0071\u002c\u005e\u0075\u0035\u003e\u0034\u004f\u0065\u0077\u0058\u0074\u0045\u0053\u0040\u0079\u002b\u0073\u003e\u002e\u0032\u0048\u004e\u0029\u0029\u0032\u0046\u0023\u0066\u0022\u0078\u0075\u0048\u003e\u0059\u0078\u004e\u007c\u0047\u0051\u0058\u002e\u0072\u002f\u003c\u0067\u002e\u005d\u0065\u006d\u0046\u002e\u0058\u003c\u0028\u0075\u006b\u004e\u0054\u0064\u007a\u0044\u007d\u0068\u0041\u006a\u0070\u006c\u0038\u0041\u004c\u0033\u007c\u0065\u006a\u0059\u0044\u0069\u006d\u006a\u0040\u002f\u006e\u0053\u0032\u0062\u0059\u006a\u0069\u002f\u006a\u0024\u0031\u0024\u0046\u0040\u0056\u003f\u0066\u0057\u005d\u006d\u0043\u006e\u0070\u0033\u004e\u0037\u0052\u007e\u0063\u0055\u0040\u0026\u0037\u007a\u0029\u004a\u0029\u004e\u0045\u0062\u0063\u003b\u0042\u006f\u0077\u005b\u007b\u0029\u003d\u0079\u0064\u0055\u0065\u0056\u0070\u0063\u0021\u0029\u0063\u0055\u0031\u0045\u0057\u0079\u0059\u0054\u0053\u0052\u0041\u0038\u0074\u0067\u002e\u005d\u0065\u006d\u0046\u0055\u006a\u0061\u0060\u004e\u004e\u0064\u0054\u003f\u0066\u005d\u007d\u005f\u0052\u006d\u0066\u0062\u0030\u0066\u0059\u002f\u0048\u0060\u006a\u0030\u0064\u007e\u0059\u0054\u0069\u0043\u0069\u003f\u0032\u0048\u0067\u0070\u0021\u007a\u0044\u005b\u0056\u0076\u0047\u007b\u002f\u0045\u0038\u0071\u0059\u006e\u0079\u0035\u0058\u0029\u005f\u0044\u0069\u0058\u005a\u007c\u0060\u0037\u0060\u004a\u0035\u004b\u0044\u0063\u003c\u0051\u0075\u0078\u0057\u0021\u0062\u007b\u0025\u0035\u0077\u0039\u0071\u0064\u0043\u0059\u0074\u0068\u0060\u006a\u0050\u0050\u0022\u0043\u002e\u002a\u005e\u0024\u0071\u005f\u0056\u0048\u0038\u0049\u006a\u005e\u0061\u0047\u002c\u0036\u0044\u0075\u007b\u004d\u0042\u0066\u0057\u0030\u006e\u003b\u0073\u004d\u0079\u0071\u0028\u0063\u004c\u004a\u0047\u006b\u0047\u0044\u002f\u0062\u0049\u0058\u005a\u006f\u0055\u004e\u0059\u0040\u0048\u0041\u006a\u0065\u0063\u006b\u0052\u0056\u0045\u003f\u0077\u0078\u0035\u005b\u0046\u0071\u0031\u0077\u003d\u0047\u0058\u003d\u0037\u0045\u005d\u0029\u0069\u0052\u006d\u0048\u0073\u003e\u0069\u005d\u0042\u0077\u0043\u0029\u002b\u0067\u006d\u0031\u0037\u002e\u0032\u0048\u0062\u0059\u0021\u003a\u0041\u0033\u0066\u0062\u0044\u0025\u0042\u004a\u006e\u0028\u004c\u0051\u0059\u0057\u002e\u006e\u0037\u0035\u002f\u0049\u007d\u0022\u0077\u007d\u006f\u0055\u002e\u0059\u0044\u0069\u006d\u006a\u005f\u003d\u0052\u0072\u006a\u0025\u006c\u004a\u0067\u0043\u0053\u0075\u0074\u0072\u0024\u002c\u002c\u002f\u004b\u0049\u0030\u003c\u006c\u004a\u0066\u0028\u0024\u0075\u0022\u0068\u003a\u006a\u003b\u007c\u0067\u0048\u0057\u004e\u0071\u0079\u003b\u003c\u0058\u006a\u002b\u0041\u0053\u006a\u0029\u0062\u0078\u0074\u0035\u007b\u0078\u005b\u0028\u0077\u0028\u005e\u0049\u0041\u0049\u005b\u0024\u004e\u0071\u0069\u0048\u0055\u0039\u0021\u0072\u0050\u0052\u0051\u0065\u007d\u003f\u0077\u003d\u0037\u0034\u0066\u0029\u0059\u005f\u0032\u004c\u003c\u005a\u007c\u0065\u0057\u006a\u0061\u0061\u003e\u0062\u006c\u0052\u0044\u0025\u003c\u0031\u0052\u0066\u0032\u0025\u004a\u0075\u003e\u0075\u0028\u0042\u006a\u0025\u007c\u0064\u002f\u006d\u0077\u004b